{"command":"python3 - <<'PY'
import json
from collections import OrderedDict

config=json.load(open('/root/config.json'))
block_size=config['block_size']
cap=config['cache_capacity_blocks']
small_cap=round(cap*config['s3fifo']['small_ratio'])
main_cap=cap-small_cap
max_freq=config['s3fifo']['max_freq']

def incf(f):
    return f+1 if f < max_freq else max_freq

S=OrderedDict()  # key->freq
M=OrderedDict()
G=OrderedDict()  # key->None, FIFO order

per=[]
total_prompt=0
total_hit=0


def insert_G(h):
    if h in G:
        del G[h]
    elif len(G) >= main_cap:
        G.popitem(last=False)
    G[h]=None


def admit_to_M(h,freq):
    while len(M) >= main_cap:
        victim,vf = next(iter(M.items()))
        if vf >= 1:
            # second chance
            del M[victim]
            M[victim]=vf-1
        else:
            del M[victim]
            insert_G(victim)
            break
    M[h]=freq


def admit_to_S(h):
    while len(S) >= small_cap:
        victim,vf = S.popitem(last=False)
        if vf >= 1:
            admit_to_M(victim,vf)
        else:
            insert_G(victim)
    S[h]=0

for idx,line in enumerate(open('/root/trace.jsonl')):
    if not line.strip():
        continue
    req=json.loads(line)
    hashes=req['hash_ids']
    L=req['input_length']
    total_prompt += L
    k=0
    for h in hashes:
        if h in S or h in M:
            k += 1
        else:
            break
    hit_tokens=min(k*block_size, L)
    total_hit += hit_tokens
    per.append({'idx': idx, 'prompt_tokens': L, 'hit_tokens': hit_tokens})

    # access all blocks
    for h in hashes:
        if h in S:
            S[h]=incf(S[h])
        elif h in M:
            M[h]=incf(M[h])
        elif h in G:
            del G[h]
            admit_to_M(h,0)
        else:
            admit_to_S(h)

report={
    'total_requests': len(per),
    'total_prompt_tokens': total_prompt,
    'total_hit_tokens': total_hit,
    'overall_hit_rate': total_hit/total_prompt if total_prompt else 0,
    'final_cache_blocks': len(S)+len(M),
    'per_request': per,
}
open('/root/report.json','w').write(json.dumps(report,separators=(',',':')))
print('done', len(per), total_prompt, total_hit, len(S)+len(M))
PY"}
